<?php require '../includes/core.php';$u=require_user(true);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');$target=db()->prepare('SELECT id,role,avatar_file FROM users WHERE id=?');$target->execute([$id]);$person=$target->fetch();if(!$person)$error='Usuário não encontrado.';elseif((int)$id===(int)$u['id'])$error='Você não pode modificar sua própria conta por aqui.';elseif($person['role']==='admin')$error='Não é permitido modificar outras contas administrativas por este painel.';elseif($action==='remove_avatar'){
  if(empty($person['avatar_file'])){$error='Esse usuário não possui foto de perfil.';}
  else{
   $file=basename((string)$person['avatar_file']);
   $stmt=db()->prepare('UPDATE users SET avatar_file=NULL WHERE id=?');
   $stmt->execute([$id]);
   if(preg_match('/^[a-f0-9]{32}\.(?:jpg|png|webp)$/D',$file)){
     $path=dirname(__DIR__).'/uploads/avatars/'.$file;
     if(is_file($path))@unlink($path);
   }
   notify('Foto do usuário removida.');go('admin/users.php');
  }
 }elseif($action==='toggle_block'){db()->prepare('UPDATE users SET is_blocked=1-is_blocked WHERE id=?')->execute([$id]);notify('Situação da conta atualizada.');go('admin/users.php');}elseif($action==='revoke'){db()->beginTransaction();try{db()->prepare("UPDATE subscriptions SET status='cancelled' WHERE user_id=? AND status='active'")->execute([$id]);db()->prepare('UPDATE users SET active_plan=NULL,plan_expires_at=NULL WHERE id=?')->execute([$id]);db()->commit();notify('Assinatura revogada.');go('admin/users.php');}catch(Throwable $e){db()->rollBack();$error='Não foi possível revogar.';}}else $error='Ação inválida.';}$s=db()->query('SELECT id,name,email,role,is_blocked,active_plan,plan_expires_at,created_at,avatar_file FROM users ORDER BY id DESC');layout_start('Gerenciar usuários',$u);?><span class="kicker">ADMIN • CLIENTES</span><h1 class="page-title">Gerenciar usuários</h1><p class="muted">Visualize perfis, modere fotos, acompanhe assinaturas e gerencie acessos. Sem apagar os dados dos chamados.</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><div class="card table-wrap"><table class="table"><thead><tr><th>Membro</th><th>E-mail</th><th>Perfil</th><th>Assinatura</th><th>Acesso</th><th>Ações</th></tr></thead><tbody><?php foreach($s as $r):?><tr><td><div class="member-cell"><div class="member-photo"><?php if(!empty($r['avatar_file'])):?><img src="<?=h(url('uploads/avatars/'.rawurlencode($r['avatar_file'])))?>" alt="Foto de <?=h($r['name'])?>" loading="lazy" onerror="this.style.display='none'" /><?php else:?><span><?=h(mb_strtoupper(mb_substr($r['name'],0,1)))?></span><?php endif;?></div><strong><?=h($r['name'])?></strong></div></td><td><?=h($r['email'])?></td><td><?=h($r['role'])?></td><td><?=has_subscription($r)?h($r['active_plan']).' • até '.date('d/m/Y',strtotime($r['plan_expires_at'])):'Sem plano ativo'?></td><td><span class="pill <?=empty($r['is_blocked'])?'ok':''?>"><?=!empty($r['is_blocked'])?'Bloqueado':'Liberado'?></span></td><td><?php if($r['role']!=='admin'):?><div class="actions member-actions"><?php if(!empty($r['avatar_file'])):?><form method="post" onsubmit="return confirm('Remover a foto de perfil deste membro?')"><input type="hidden" name="csrf" value="<?=h(token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="action" value="remove_avatar"><button type="submit" class="btn secondary small remove-photo-btn">Remover foto</button></form><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="toggle_block"><button class="btn secondary small"><?=!empty($r['is_blocked'])?'Liberar':'Bloquear'?></button></form><?php if(has_subscription($r)):?><form method="post" onsubmit="return confirm('Revogar a assinatura deste usuário?')"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="revoke"><button class="btn secondary small">Revogar plano</button></form><?php endif;?></div><?php else:?>Conta protegida<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php layout_end();?>